import React, { ReactNode } from 'react';

import { _sanitizeSymbol as sanitizeSymbol } from '../../../../../../../core/utils/sanitize-symbol.js';
import { DefaultMarkerIcon } from '../../../../annotations-atoms/components/DefaultMarkerIcon.js';

export function getSymbol(symbol: string | ReactNode): string | ReactNode {
  if (symbol) {
    if (typeof symbol !== 'string') {
      return <>{symbol}</>;
    } else {
      return sanitizeSymbol(symbol);
    }
  } else {
    return <DefaultMarkerIcon />;
  }
}
